<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Correct & Reapply · MEETA Vendor</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@600;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{--paper:#faf3ea;--card:#fffdf9;--ink:#3c2e21;--muted:#776650;--line:#e6d7c1;--terra:#b9532a;--terra-dark:#963e1d;--danger:#a63d38;--danger-soft:#fbe5df;--success:#39734b;--success-soft:#e3f1e6;--warn:#9a671b;--warn-soft:#f9ecd4}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 Inter,sans-serif}a{text-decoration:none;color:inherit}.top{height:76px;background:var(--card);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100vw - 1180px)/2));position:sticky;top:0;z-index:10}.logo{font:700 25px Fraunces,serif}.logo span{color:var(--terra)}.top small{display:block;color:var(--muted);font:10px Inter,sans-serif;letter-spacing:.16em;text-transform:uppercase}.logout{border:1px solid var(--line);background:white;padding:10px 15px;border-radius:8px;cursor:pointer}.wrap{max-width:1180px;margin:42px auto 80px;padding:0 24px}.hero{display:grid;grid-template-columns:1fr 330px;gap:22px}.hero-main,.side,.section{background:var(--card);border:1px solid var(--line);border-radius:16px}.hero-main{padding:34px}.badge{display:inline-flex;align-items:center;gap:7px;background:var(--danger-soft);color:var(--danger);font-weight:700;font-size:11px;letter-spacing:.08em;text-transform:uppercase;border-radius:30px;padding:7px 12px}.badge:before{content:'';width:7px;height:7px;border-radius:50%;background:currentColor}.hero h1{font:700 38px/1.15 Fraunces,serif;margin:18px 0 9px}.hero p{color:var(--muted);margin:0;max-width:700px}.reason{margin-top:25px;background:#fff7f4;border-left:4px solid var(--danger);padding:17px 19px}.reason small{display:block;color:var(--danger);font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px}.reason div{white-space:pre-wrap}.side{padding:26px}.side h3{font:700 20px Fraunces,serif;margin:0 0 12px}.side ol{padding-left:20px;color:var(--muted);margin:0}.side li{padding:5px 0}.section{margin-top:22px;padding:28px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:20px}.section h2{font:700 26px Fraunces,serif;margin:0}.section-head p{margin:4px 0 0;color:var(--muted)}.progress{font-weight:700;color:var(--terra)}.checks{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.check{border:1px solid var(--line);border-radius:12px;padding:18px;display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:13px}.check-icon{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--warn-soft);color:var(--warn);font-weight:700}.check.complete .check-icon{background:var(--success-soft);color:var(--success)}.check.issue{border-color:#e7aaa4;background:#fffafa}.check strong{display:block}.check p{font-size:12px;color:var(--muted);margin:3px 0 0}.edit{color:var(--terra);font-weight:700;border:1px solid #deb59e;padding:8px 11px;border-radius:8px;white-space:nowrap}.document-notes{margin-top:16px;display:none}.doc-note{background:var(--danger-soft);color:#84342f;padding:12px 14px;margin-top:8px;border-radius:8px}.submit-bar{margin-top:22px;background:#34271e;color:white;border-radius:16px;padding:24px 28px;display:flex;align-items:center;justify-content:space-between;gap:22px}.submit-bar h3{font:700 21px Fraunces,serif;margin:0 0 4px}.submit-bar p{color:#d8c9bc;margin:0;font-size:12px}.submit{border:0;background:var(--terra);color:white;padding:13px 22px;border-radius:9px;font-weight:700;cursor:pointer;white-space:nowrap}.submit:disabled{opacity:.45;cursor:not-allowed}.message{display:none;margin-top:15px;padding:13px;border-radius:8px}.message.error{display:block;background:var(--danger-soft);color:var(--danger)}.loading{text-align:center;padding:100px;color:var(--muted)}@media(max-width:800px){.hero{grid-template-columns:1fr}.checks{grid-template-columns:1fr}.hero h1{font-size:31px}.submit-bar{align-items:flex-start;flex-direction:column}.submit{width:100%}.top{padding:0 18px}}
</style>
</head>
<body>
<header class="top"><a class="logo" href="/">MEETA<span>.</span><small>Vendor application centre</small></a><button class="logout" id="logout">Sign out</button></header>
<main class="wrap"><div id="loader" class="loading">Loading your application review…</div><div id="content" hidden>
<section class="hero"><div class="hero-main"><span class="badge">Changes requested</span><h1>Your application can be corrected and resubmitted.</h1><p>Review the feedback, update only the sections that need attention, then send your application back to the MEETA verification team.</p><div class="reason"><small>Admin feedback</small><div id="reason">No specific feedback was provided. Please review every section before reapplying.</div></div></div><aside class="side"><h3>What happens next?</h3><ol><li>Correct your business details or rejected documents.</li><li>Review the complete application.</li><li>Reapply for verification.</li><li>Your status changes to Pending Review.</li></ol></aside></section>
<section class="section"><div class="section-head"><div><h2>Application checklist</h2><p>Every required section must be complete before you can reapply.</p></div><div class="progress" id="progress">Checking…</div></div><div class="checks">
<article class="check" id="profileCheck"><span class="check-icon">!</span><div><strong>Business profile</strong><p id="profileText">Checking store and business details…</p></div><a class="edit" href="/vendor/profile?return=/vendor/rejected">Edit</a></article>
<article class="check" id="addressCheck"><span class="check-icon">!</span><div><strong>Business address</strong><p id="addressText">Checking registered address…</p></div><a class="edit" href="/vendor/address?return=/vendor/rejected">Edit</a></article>
<article class="check" id="bankCheck"><span class="check-icon">!</span><div><strong>Settlement account</strong><p id="bankText">Checking bank details…</p></div><a class="edit" href="/vendor/bank-account?return=/vendor/rejected">Edit</a></article>
<article class="check" id="documentsCheck"><span class="check-icon">!</span><div><strong>Required documents</strong><p id="documentsText">Checking PAN, Aadhaar and settlement proof…</p></div><a class="edit" href="/vendor/documents?return=/vendor/rejected">Review</a></article>
</div><div class="document-notes" id="documentNotes"></div><div id="message" class="message"></div></section>
<section class="submit-bar"><div><h3>Ready for another review?</h3><p>Submitting confirms that you have corrected the requested information. You will not be able to edit while verification is pending.</p></div><button class="submit" id="submit" disabled>Reapply for verification</button></section>
</div></main>
<script>
const token=localStorage.getItem('meeta_token'),headers={Accept:'application/json',Authorization:'Bearer '+token};if(!token)location.href='/login';const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));let ready=false;
async function api(path,options={}){const response=await fetch('/api/vendor/'+path,{...options,headers:{...headers,...(options.headers||{})}});const json=await response.json().catch(()=>({}));if(response.status===401){localStorage.removeItem('meeta_token');location.href='/login';throw Error('Session expired')}if(!response.ok||json.success===false)throw Object.assign(Error(json.message||'Unable to load application'),{errors:json.errors});const data=json.data;return path==='address'&&Array.isArray(data)?(data[0]||null):data}
function mark(id,complete,text,issue=false){const card=document.getElementById(id+'Check');card.classList.toggle('complete',complete);card.classList.toggle('issue',issue);card.querySelector('.check-icon').textContent=complete?'✓':'!';document.getElementById(id+'Text').textContent=text;return complete}
async function load(){try{const [profile,address,bank,documents]=await Promise.all([api('profile'),api('address').catch(()=>null),api('bank-account').catch(()=>null),api('documents').catch(()=>[])]);if(profile.status==='pending')return location.href='/vendor/pending';if(profile.status==='approved')return location.href='/vendor/dashboard';if(profile.status!=='rejected')return location.href='/vendor/profile';document.getElementById('reason').textContent=profile.rejection_reason||'No specific feedback was provided. Please review every section before reapplying.';const profileOk=mark('profile',Boolean(profile.store_name&&profile.business_name),profile.store_name&&profile.business_name?`${profile.store_name} · ${profile.business_name}`:'Store name and business name are required.');const addressOk=mark('address',Boolean(address?.id),address?.id?`${address.city}, ${address.state} · ${address.postal_code}`:'Add your registered business address.');const bankOk=mark('bank',Boolean(bank?.id),bank?.id?`${bank.bank_name} · account ending ${String(bank.account_number||'').slice(-4)}`:'Add an account for marketplace settlements.');const required=['pan','aadhaar','cancelled_cheque'],latest={};documents.forEach(doc=>{if(!latest[doc.document_type])latest[doc.document_type]=doc});const rejected=required.map(type=>latest[type]).filter(doc=>doc?.status==='rejected'),missing=required.filter(type=>!latest[type]);const documentsOk=!missing.length&&!rejected.length;mark('documents',documentsOk,documentsOk?'All required documents are ready for verification.':missing.length?`Missing: ${missing.map(x=>x.replaceAll('_',' ').toUpperCase()).join(', ')}`:'Replace the rejected document(s) shown below.',rejected.length>0);if(rejected.length){const notes=document.getElementById('documentNotes');notes.style.display='block';notes.innerHTML='<strong>Document feedback</strong>'+rejected.map(doc=>`<div class="doc-note"><strong>${esc(doc.document_type).replaceAll('_',' ').toUpperCase()}</strong> — ${esc(doc.remarks||'Please upload a clear, valid replacement.')}</div>`).join('')}ready=[profileOk,addressOk,bankOk,documentsOk].every(Boolean);document.getElementById('progress').textContent=`${[profileOk,addressOk,bankOk,documentsOk].filter(Boolean).length} of 4 complete`;document.getElementById('submit').disabled=!ready;document.getElementById('loader').hidden=true;document.getElementById('content').hidden=false}catch(error){document.getElementById('loader').textContent=error.message}}
document.getElementById('submit').onclick=async()=>{const button=document.getElementById('submit'),message=document.getElementById('message');if(!ready)return;button.disabled=true;button.textContent='Submitting…';message.className='message';try{await api('submit',{method:'POST'});location.href='/vendor/pending'}catch(error){message.className='message error';message.textContent=error.errors?Object.values(error.errors).flat().join(' '):error.message;button.disabled=false;button.textContent='Reapply for verification'}};document.getElementById('logout').onclick=()=>{localStorage.removeItem('meeta_token');localStorage.removeItem('meeta_user');localStorage.removeItem('meeta_vendor');location.href='/login'};load();
</script>
</body></html>
